local _PADDED_STREAM = table.concat(LARGE_PADDED_DATA, "")

-- Polyfill otomatis jika bit32 tidak ditemukan (Anti-32bit Environment Crack)
local bit32 = rawget(_G, "bit32") or bit32 or {}
if not bit32.bxor then
    bit32.bxor = function(a, b)
        local r, m = 0, 1
        while a > 0 or b > 0 do
            if a % 2 ~= b % 2 then r = r + m end
            a, b, m = math.floor(a / 2), math.floor(b / 2), m * 2
        end
        return r
    end
    bit32.band = function(a, b)
        local r, m = 0, 1
        while a > 0 and b > 0 do
            if a % 2 == 1 and b % 2 == 1 then r = r + m end
            a, b, m = math.floor(a / 2), math.floor(b / 2), m * 2
        end
        return r
    end
    bit32.rshift = function(a, disp) return math.floor(a / (2 ^ disp)) end
    bit32.lshift = function(a, disp) return (a * (2 ^ disp)) % 4294967296 end
end

-- [PROTEKSI MEMORI TINGKAT TINGGI: DOUBLE-LAYER DECRYPTOR]
local function _ULTIMATE_DECRYPT(str, seed)
    if #_PADDED_STREAM < 1000 then return nil end
    local len = #str
    local out = table.create(len)
    local key = bit32.band(seed or 0x5A, 0xFFFFFFFF)
    for i = 1, len do
        key = bit32.band(bit32.bxor(key, bit32.lshift(i, 3) + 0x1F), 0xFFFFFFFF)
        out[i] = string.char(bit32.bxor(string.byte(str, i), bit32.band(key, 0xFF)))
    end
    return table.concat(out)
end

-- [CONTAINER GUI ANTI-DETEKSI TOTAL]
local function GetHardenedParent()
    local target = nil
    pcall(function()
        target = (gethui and gethui()) 
            or game:GetService("CoreGui"):FindFirstChild("RobloxGui") 
            or game:GetService("CoreGui")
    end)
    return target or game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
end

-- [ADAPTIVE HASH-BASED SCANNER (ANTI GAME UPDATE)]
local DYNAMIC_REMOTE = nil
local DYNAMIC_BALL_FOLDER = nil
local DYNAMIC_ABILITY_REMOTE = nil

local CachedServices = setmetatable({}, {
    __index = function(t, k)
        local s = game:GetService(k)
        t[k] = s
        return s
    end
})

local function SuperScan()
    local repStorage = CachedServices.ReplicatedStorage
    if repStorage then
        local targets = {"parry", "hit", "swing", "ball"}
        local abTargets = {"ability", "useability", "activateability", "skill"}
        local children = repStorage:GetChildren()
        
        for i = 1, #children do
            local obj = children[i]
            if obj:IsA("RemoteEvent") then
                local n = obj.Name:lower()
                for j = 1, #targets do
                    if n:find(targets[j], 1, true) then
                        DYNAMIC_REMOTE = obj
                    end
                end
                for k = 1, #abTargets do
                    if n:find(abTargets[k], 1, true) then
                        DYNAMIC_ABILITY_REMOTE = obj
                    end
                end
            end
        end
    end

    local wsChildren = workspace:GetChildren()
    for i = 1, #wsChildren do
        local obj = wsChildren[i]
        if obj:IsA("Folder") or obj:IsA("Model") then
            if obj.Name:lower():find("ball") or obj:GetAttribute("Target") then
                DYNAMIC_BALL_FOLDER = obj
                break
            end
        end
    end
end
SuperScan()

