-- [CORE ENGINE: HIGH-FREQUENCY VECTOR3 LOOP - 64-BIT OPTIMIZED]
local lastParryTime = 0
RunService.PreSimulation:Connect(function()
    if not Toggles.AutoParry or not DYNAMIC_REMOTE then return end
    
    local character = LocalPlayer.Character
    local hrp = character and character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    
    -- Cari bola aktif di folder game
    local currentBall = nil
    if DYNAMIC_BALL_FOLDER then
        for _, b in ipairs(DYNAMIC_BALL_FOLDER:GetChildren()) do
            if b:IsA("BasePart") then
                currentBall = b
                break
            end
        end
    end
    
    if not currentBall then 
        Visual_Sphere.Parent = nil
        return 
    end
    
    -- Kelola Fitur ESP Visual secara dinamis
    if Toggles.BallESP then
        if ESP_Highlight.Parent ~= currentBall then
            ESP_Highlight.Parent = currentBall
            ESP_Highlight.Enabled = true
        end
    else
        ESP_Highlight.Enabled = false
    end
    
    if Toggles.VisualHitbox then
        Visual_Sphere.Size = Vector3.new(Config.HitboxSize, Config.HitboxSize, Config.HitboxSize)
        Visual_Sphere.Position = hrp.Position
        if Visual_Sphere.Parent ~= workspace then Visual_Sphere.Parent = workspace end
    else
        Visual_Sphere.Parent = nil
    end
    
    -- Kalkulasi Vektor Jarak & Refleks Arah Bola (Dot Product)
    local myPos = hrp.Position
    local ballPos = currentBall.Position
    local ballVelocity = currentBall.AssemblyLinearVelocity
    local distance = (myPos - ballPos).Magnitude
    
    local directionToMe = (myPos - ballPos).Unit
    local isHeadingToMe = ballVelocity.Unit:Dot(directionToMe) > 0
    
    if Toggles.AntiCurve then
        isHeadingToMe = isHeadingToMe or (ballVelocity.Magnitude > 55 and distance < 40)
    end
    if currentBall:GetAttribute("Target") == LocalPlayer.Name then
        isHeadingToMe = true
    end
    
    if isHeadingToMe then
        -- [DYNAMIC HUMANIZED DELAY ADAPTATION]
        local currentPing = Stats.Network.ServerStatsItem["Data Ping"]:GetValue() / 1000
        local triggerDist = Config.MaxDistance
        
        if Toggles.PredictionMode then
            triggerDist = triggerDist + (ballVelocity.Magnitude * (currentPing + 0.015))
        else
            triggerDist = triggerDist + (ballVelocity.Magnitude * currentPing)
        end
        
        -- AUTO SPAM MODE (Clash)
        if Toggles.AutoSpam and distance <= Config.SpamDistance then
            DYNAMIC_REMOTE:FireServer()
            lastParryTime = os.clock()
            return
        end
        
        -- AUTO ABILITY
        if Toggles.AutoAbility and distance <= (triggerDist * 1.5) and ballVelocity.Magnitude > 120 and DYNAMIC_ABILITY_REMOTE then
            DYNAMIC_ABILITY_REMOTE:FireServer()
        end
        
        if distance <= triggerDist and (os.clock() - lastParryTime) > 0.05 then
            lastParryTime = os.clock()
            DYNAMIC_REMOTE:FireServer()
        end
    end
end)

