local function RenderToggle(name, displayName, callback)
    local Row = Instance.new("Frame")
    Row.Size = UDim2.new(0.9, 0, 0, 40)
    Row.BackgroundColor3 = Color3.fromRGB(18, 18, 28)
    Row.BorderSizePixel = 0
    Row.Parent = ContentContainer
    Instance.new("UICorner", Row).CornerRadius = UDim.new(0, 6)
    
    local Lbl = Instance.new("TextLabel")
    Lbl.Size = UDim2.new(0.6, 0, 1, 0)
    Lbl.Position = UDim2.fromOffset(10, 0)
    Lbl.BackgroundTransparency = 1
    Lbl.Text = displayName
    Lbl.TextColor3 = Color3.fromRGB(230, 230, 230)
    Lbl.Font = Enum.Font.GothamSemibold
    Lbl.TextSize = 14
    Lbl.TextXAlignment = Enum.TextXAlignment.Left
    Lbl.Parent = Row
    
    local Btn = Instance.new("TextButton")
    Btn.Size = UDim2.fromOffset(45, 22)
    Btn.Position = UDim2.new(1, -55, 0.5, -11)
    Btn.BackgroundColor3 = Toggles[name] and Color3.fromRGB(0, 255, 150) or Color3.fromRGB(40, 40, 50)
    Btn.Text = ""
    Btn.Parent = Row
    Instance.new("UICorner", Btn).CornerRadius = UDim.new(0, 11)
    
    Btn.MouseButton1Click:Connect(function()
        Toggles[name] = not Toggles[name]
        TweenService:Create(Btn, TweenInfo.new(0.2), {
            BackgroundColor3 = Toggles[name] and Color3.fromRGB(0, 255, 150) or Color3.fromRGB(40, 40, 50)
        }):Play()
        callback(Toggles[name])
    end)
end

local function RenderSlider(configName, displayName, min, max, callback)
    local Row = Instance.new("Frame")
    Row.Size = UDim2.new(0.9, 0, 0, 50)
    Row.BackgroundColor3 = Color3.fromRGB(18, 18, 28)
    Row.BorderSizePixel = 0
    Row.Parent = ContentContainer
    Instance.new("UICorner", Row).CornerRadius = UDim.new(0, 6)
    
    local Lbl = Instance.new("TextLabel")
    Lbl.Size = UDim2.new(0.5, 0, 0, 25)
    Lbl.Position = UDim2.fromOffset(10, 2)
    Lbl.BackgroundTransparency = 1
    Lbl.Text = displayName
    Lbl.TextColor3 = Color3.fromRGB(230, 230, 230)
    Lbl.Font = Enum.Font.GothamSemibold
    Lbl.TextSize = 13
    Lbl.TextXAlignment = Enum.TextXAlignment.Left
    Lbl.Parent = Row
    
    local ValLbl = Instance.new("TextLabel")
    ValLbl.Size = UDim2.new(0.4, 0, 0, 25)
    ValLbl.Position = UDim2.new(1, -10, 0, 2)
    ValLbl.BackgroundTransparency = 1
    ValLbl.Text = tostring(Config[configName])
    ValLbl.TextColor3 = Color3.fromRGB(0, 255, 180)
    ValLbl.Font = Enum.Font.GothamBold
    ValLbl.TextSize = 13
    ValLbl.TextXAlignment = Enum.TextXAlignment.Right
    ValLbl.Parent = Row

    local SliderBar = Instance.new("TextButton")
    SliderBar.Size = UDim2.new(0.92, 0, 0, 6)
    SliderBar.Position = UDim2.new(0.04, 0, 0.7, 0)
    SliderBar.BackgroundColor3 = Color3.fromRGB(45, 45, 60)
    SliderBar.Text = ""
    SliderBar.Parent = Row
    Instance.new("UICorner", SliderBar)

    local SliderFill = Instance.new("Frame")
    SliderFill.Size = UDim2.new((Config[configName] - min)/(max - min), 0, 1, 0)
    SliderFill.BackgroundColor3 = Color3.fromRGB(0, 255, 180)
    SliderFill.BorderSizePixel = 0
    SliderFill.Parent = SliderBar
    Instance.new("UICorner", SliderFill)

    local isSliding = false
    local function UpdateSlider(input)
        local posX = math.clamp((input.Position.X - SliderBar.AbsolutePosition.X) / SliderBar.AbsoluteSize.X, 0, 1)
        SliderFill.Size = UDim2.new(posX, 0, 1, 0)
        local calculatedVal = math.floor(min + (posX * (max - min)))
        Config[configName] = calculatedVal
        ValLbl.Text = tostring(calculatedVal)
        callback(calculatedVal)
    end

    SliderBar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isSliding = true
            UpdateSlider(input)
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if isSliding and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            UpdateSlider(input)
        end
    end)

    UserInputService.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isSliding = false
        end
    end)
end

